tool_input.old_string:
/* Primary Flight Display Styles - Professional Glass Cockpit Layout */
.pfd-container {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.pfd-main {
    display: flex;
    gap: 0.5rem;
    justify-content: center;
    align-items: flex-start;
    background: #000011;
    border-radius: 8px;
    padding: 0.5rem;
}

.pfd-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
}

.flight-mode-display {
    position: absolute;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(0, 0, 0, 0.8);
    color: #00FF00;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-weight: 600;
    font-size: 0.9rem;
    font-family: 'Courier New', monospace;
    border: 1px solid #00AA00;
    z-index: 10;
}

canvas {
    border: 2px solid #333366;
    border-radius: 6px;
    background: #000011;
    box-shadow: 0 0 10px rgba(0, 150, 255, 0.3);
}

#attitude-indicator {
    background: radial-gradient(circle at center, #000022 0%, #000011 100%);
    border: 2px solid #4169E1;
    box-shadow: 0 0 15px rgba(65, 105, 225, 0.4);
}

#airspeed-tape, #altitude-tape {
    background: linear-gradient(to bottom, #000011 0%, #000022 50%, #000011 100%);
    border: 2px solid #32CD32;
    box-shadow: 0 0 8px rgba(50, 205, 50, 0.3);
}

/* Professional Aviation-Style PFD Info Panel */
.pfd-info {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: linear-gradient(145deg, #000011, #000022);
    border-radius: 8px;
    padding: 0.75rem;
    border: 1px solid #333366;
}

.pfd-status {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 0.5rem;
}

/* Professional Armed Status Indicator */
.armed-status {
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-weight: 700;
    font-size: 1rem;
    text-align: center;
    font-family: 'Courier New', monospace;
    background: #666666;
    color: white;
    border: 2px solid #888888;
    box-shadow: 0 0 5px rgba(255, 68, 68, 0.3);
    transition: all 0.3s ease;
}

.armed-status.armed {
    background: #FF4444;
    border-color: #FF6666;
    box-shadow: 0 0 10px rgba(255, 68, 68, 0.6);
    animation: pulse 2s infinite;
}

/* Legacy flight mode display with professional styling */
.flight-mode {
    padding: 0.5rem 1rem;
    background: linear-gradient(145deg, #001122, #002233);
    border-radius: 6px;
    font-weight: 600;
    font-family: 'Courier New', monospace;
    color: #00CCFF;
    border: 1px solid #0066CC;
}

/* Professional telemetry displays */
.pfd-telemetry {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.telemetry-row {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
}

.telemetry-item {
    padding: 0.5rem;
    background: linear-gradient(145deg, #000022, #001133);
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
    font-family: 'Courier New', monospace;
    text-align: center;
    flex: 1;
    color: #00FF00;
    border: 1px solid #006600;
    box-shadow: 0 0 3px rgba(0, 255, 0, 0.3);
    transition: all 0.3s ease;
}

/* GPS status gets special aviation styling */
#gps-status {
    color: #00CCFF;
    border-color: #0066CC;
    box-shadow: 0 0 3px rgba(0, 204, 255, 0.3);
}

/* Position display with coordinate styling */
#position-display {
    font-size: 0.8rem;
    letter-spacing: 0.5px;
    color: #FFCC00;
    border-color: #CC9900;
    box-shadow: 0 0 3px rgba(255, 204, 0, 0.3);
}

