    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    z-index: 10;
}

.top-status-bar {
    position: absolute;
    top: 8px;
    left: 8px;
    right: 8px;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
}

.flight-mode-indicator {
    background: rgba(0, 0, 0, 0.85);
    color: #00ff88;
    padding: 4px 12px;
    border-radius: 4px;
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
    border: 1px solid #00aa66;
    box-shadow: 0 0 8px rgba(0, 255, 136, 0.3);
}

.armed-indicator {
    background: rgba(0, 0, 0, 0.85);
    color: #00ff88;
    padding: 4px 12px;
    border-radius: 4px;
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
    border: 1px solid #666;
    transition: all 0.3s ease;
}

.armed-indicator.armed {
    color: #ff4444;
    border-color: #ff4444;
    box-shadow: 0 0 12px rgba(255, 68, 68, 0.5);
    animation: pulse-armed 2s infinite;
}

.bottom-info-bar {
    position: absolute;
    bottom: 8px;
    left: 8px;
    right: 8px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
}

.system-status {
    display: flex;
    gap: 12px;
}

.status-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(0, 0, 0, 0.8);
    padding: 4px 8px;
    border-radius: 4px;
    border: 1px solid #333;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
}

.status-label {
    font-family: 'Arial', sans-serif;
    font-size: 9px;
    font-weight: 500;
    color: #87ceeb;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
}

.status-value {
    font-family: 'Courier New', monospace;
    font-size: 11px;
    font-weight: 600;
    color: #00ff88;
}

.position-info {
    background: rgba(0, 0, 0, 0.8);
    padding: 4px 10px;
    border-radius: 4px;
    border: 1px solid #333;
}

.coordinates {
    font-family: 'Courier New', monospace;
    font-size: 10px;
    color: #ffcc00;
    letter-spacing: 0.5px;
}

/* Modern Glass Cockpit Canvas Override */
canvas {
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

/* Remove old PFD styling */
.pfd-container,
.pfd-main,
.pfd-center,
.pfd-info,
.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
.armed-status,
.flight-mode {
    display: none;
}

/* Animations for modern glass cockpit */
@keyframes pulse-armed {
    0%, 100% { 
        opacity: 1;
        transform: scale(1);
    }
    50% { 
        opacity: 0.8;
        transform: scale(1.02);
    }
}

tool_input.content:
/**
 * Modern Glass Cockpit Telemetry Display Module
 * Renders an integrated G1000-style Primary Flight Display (PFD)
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;
    let ctx = null;
    let canvas = null;

    // Display constants based on modern glass cockpit design
    const DISPLAY = {
        WIDTH: 420,
        HEIGHT: 320,
        ATTITUDE_CENTER_X: 210,
        ATTITUDE_CENTER_Y: 160,
        ATTITUDE_WIDTH: 220,
        ATTITUDE_HEIGHT: 160,
        AIRSPEED_X: 20,
        AIRSPEED_WIDTH: 80,
        ALTITUDE_X: 320,
        ALTITUDE_WIDTH: 80
    };

    // Modern glass cockpit color scheme
    const COLORS = {
        SKY_BLUE: '#4169E1',
        SKY_LIGHT: '#87CEEB',
        EARTH_BROWN: '#8B4513',
        EARTH_DARK: '#2F1B14',
        HORIZON_WHITE: '#FFFFFF',
        GREEN_NORMAL: '#00FF88',
        YELLOW_CAUTION: '#FFFF00',
        RED_WARNING: '#FF4444',
        CYAN_INFO: '#00FFFF',
        MAGENTA_NAV: '#FF00FF',
        DISPLAY_BG: '#0a0a0a',
        TEXT_WHITE: '#FFFFFF',
        TEXT_GREEN: '#00FF88',
        TAPE_BG: 'rgba(10, 10, 20, 0.8)'
    };

    /**
     * Initialize Modern Glass Cockpit Display
     */
    function initialize() {
        console.log('Initializing Modern Glass Cockpit PFD...');

        // Get canvas and context
        canvas = document.getElementById('glass-pfd-display');
        if (!canvas) {
            console.error('Glass PFD canvas not found');
            return;
        }

        ctx = canvas.getContext('2d');
        if (!ctx) {
            console.error('Failed to get 2D context');
            return;
        }

        // Setup high DPI support
        setupHighDPI();

        // Setup event listeners
        setupEventListeners();

        // Start animation loop
        startAnimationLoop();

        console.log('Modern Glass Cockpit PFD initialized');
    }

    /**
     * Setup High DPI Support
     */
    function setupHighDPI() {
        const dpr = window.devicePixelRatio || 1;
        const rect = canvas.getBoundingClientRect();

        canvas.width = DISPLAY.WIDTH * dpr;
        canvas.height = DISPLAY.HEIGHT * dpr;
        ctx.scale(dpr, dpr);

        canvas.style.width = DISPLAY.WIDTH + 'px';
        canvas.style.height = DISPLAY.HEIGHT + 'px';
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            drawGlassCockpitPFD();
            updateStatusOverlays();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Draw Complete Glass Cockpit Primary Flight Display
     */
    function drawGlassCockpitPFD() {
        // Clear display with modern background
        ctx.fillStyle = COLORS.DISPLAY_BG;
        ctx.fillRect(0, 0, DISPLAY.WIDTH, DISPLAY.HEIGHT);

        // Draw integrated components
        drawAirspeedTape();
        drawRectangularAttitudeDisplay();
        drawAltitudeTape();
        drawIntegratedReadouts();
        drawFlightDirector();
    }

    /**
     * Draw Modern Rectangular Attitude Display (G1000 style)
     */
    function drawRectangularAttitudeDisplay() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const width = DISPLAY.ATTITUDE_WIDTH;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Get attitude data
        const pitch = telemetryData.pitch || 0; // degrees
        const roll = telemetryData.roll || 0;   // degrees

        ctx.save();

        // Create rectangular clipping region
        ctx.beginPath();
        ctx.rect(centerX - width/2, centerY - height/2, width, height);
        ctx.clip();

        ctx.translate(centerX, centerY);
        ctx.rotate(roll * Math.PI / 180);

        // Calculate pitch offset (modern scaling: 3 pixels per degree)
        const pitchPixels = pitch * 3;

        // Draw sky (modern blue gradient)
        const skyGradient = ctx.createLinearGradient(0, -height, 0, pitchPixels);
        skyGradient.addColorStop(0, COLORS.SKY_BLUE);
        skyGradient.addColorStop(1, COLORS.SKY_LIGHT);
        ctx.fillStyle = skyGradient;
        ctx.fillRect(-width, -height, width * 2, height + pitchPixels);

        // Draw ground (modern brown gradient)
        const groundGradient = ctx.createLinearGradient(0, pitchPixels, 0, height);
        groundGradient.addColorStop(0, COLORS.EARTH_BROWN);
        groundGradient.addColorStop(1, COLORS.EARTH_DARK);
        ctx.fillStyle = groundGradient;
        ctx.fillRect(-width, pitchPixels, width * 2, height * 2);

        // Draw horizon line (clean white line)
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-width, pitchPixels);
        ctx.lineTo(width, pitchPixels);
        ctx.stroke();

        // Draw modern pitch ladder
        drawModernPitchLadder(pitchPixels, width);

        ctx.restore();

        // Draw aircraft symbol (modern chevron style)
        drawModernAircraftSymbol(centerX, centerY);

        // Draw attitude display border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 2;
        ctx.strokeRect(centerX - width/2, centerY - height/2, width, height);
    }

    /**
     * Draw Modern Pitch Ladder (G1000 style)
     */
    function drawModernPitchLadder(pitchOffset, width) {
        const pitchAngles = [-30, -20, -15, -10, -5, 5, 10, 15, 20, 30];

        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'center';
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;

        pitchAngles.forEach(angle => {
            const y = pitchOffset - (angle * 3); // 3 pixels per degree

            if (Math.abs(y) > 150) return; // Skip if outside visible area

            const isAboveHorizon = angle > 0;
            const isMajorLine = Math.abs(angle) % 10 === 0;
            const lineLength = isMajorLine ? 60 : 30;

            // Draw pitch line
            ctx.beginPath();
            ctx.moveTo(-lineLength/2, y);
            ctx.lineTo(lineLength/2, y);
            ctx.stroke();

            // Draw angle labels for major lines
            if (isMajorLine) {
                ctx.font = '11px Arial, sans-serif';
                ctx.fillText(Math.abs(angle).toString(), -lineLength/2 - 15, y + 3);
                ctx.fillText(Math.abs(angle).toString(), lineLength/2 + 15, y + 3);
            }

            // Draw modern chevron indicators
            if (Math.abs(angle) === 5 || Math.abs(angle) === 15) {
                const chevronSize = 6;
                ctx.beginPath();
                if (isAboveHorizon) {
                    // Upward chevron
                    ctx.moveTo(-chevronSize, y + chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y + chevronSize);
                } else {
                    // Downward chevron
                    ctx.moveTo(-chevronSize, y - chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y - chevronSize);
                }
                ctx.stroke();
            }
        });
    }

    /**
     * Draw Modern Aircraft Symbol (Clean Chevron Style)
     */
    function drawModernAircraftSymbol(centerX, centerY) {
        ctx.save();
        ctx.translate(centerX, centerY);

        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 2;

        // Center dot
        ctx.beginPath();
        ctx.arc(0, 0, 2, 0, Math.PI * 2);
        ctx.fill();

        // Modern wing bars (straight lines)
        ctx.beginPath();
        ctx.moveTo(-30, 0);
        ctx.lineTo(-8, 0);
        ctx.moveTo(30, 0);
        ctx.lineTo(8, 0);
        ctx.stroke();

        // Wing tips (subtle downward angle)
        ctx.beginPath();
        ctx.moveTo(-30, 0);
        ctx.lineTo(-30, 3);
        ctx.moveTo(30, 0);
        ctx.lineTo(30, 3);
        ctx.stroke();

        ctx.restore();
    }

    /**
     * Draw Integrated Airspeed Tape (Modern Glass Style)
     */
    function drawAirspeedTape() {
        const x = DISPLAY.AIRSPEED_X;
        const width = DISPLAY.AIRSPEED_WIDTH;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Draw tape background
        ctx.fillStyle = COLORS.TAPE_BG;
        ctx.fillRect(x, centerY - height/2, width, height);

        // Get airspeed (convert m/s to knots)
        const groundSpeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        );
        const airspeedKnots = groundSpeed * 1.94384;

        const pixelsPerKnot = 2; // Modern scaling

        // Draw speed scale
        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'right';
        ctx.strokeStyle = COLORS.GREEN_NORMAL;
        ctx.fillStyle = COLORS.GREEN_NORMAL;
        ctx.lineWidth = 1;

        const minSpeed = Math.max(0, Math.floor((airspeedKnots - 30) / 10) * 10);
        const maxSpeed = Math.ceil((airspeedKnots + 30) / 10) * 10;

        for (let speed = minSpeed; speed <= maxSpeed; speed += 5) {
            const y = centerY - (speed - airspeedKnots) * pixelsPerKnot;

            if (y >= centerY - height/2 && y <= centerY + height/2) {
                const isMajorMark = speed % 10 === 0;

                ctx.beginPath();
                ctx.moveTo(x + width - (isMajorMark ? 15 : 8), y);
                ctx.lineTo(x + width, y);
                ctx.stroke();

                if (isMajorMark) {
                    ctx.fillText(speed.toString(), x + width - 20, y + 4);
                }
            }
        }

        // Draw current airspeed readout (integrated style)
        const readoutY = centerY - 12;
        ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
        ctx.fillRect(x + 5, readoutY, 45, 24);

        ctx.strokeStyle = COLORS.GREEN_NORMAL;
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 5, readoutY, 45, 24);

        ctx.fillStyle = COLORS.GREEN_NORMAL;
        ctx.textAlign = 'center';
        ctx.font = '14px Arial, sans-serif';
        ctx.fillText(Math.round(airspeedKnots).toString(), x + 27, centerY + 4);

        // Draw tape border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);
    }

    /**
     * Draw Integrated Altitude Tape (Modern Glass Style)
     */
    function drawAltitudeTape() {
        const x = DISPLAY.ALTITUDE_X;
        const width = DISPLAY.ALTITUDE_WIDTH;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Draw tape background
        ctx.fillStyle = COLORS.TAPE_BG;
        ctx.fillRect(x, centerY - height/2, width, height);

        // Get altitude (convert meters to feet)
        const altitudeMeters = telemetryData.alt_rel || 0;
        const altitudeFeet = altitudeMeters * 3.28084;

        const pixelsPerFoot = 0.15; // Modern scaling

        // Draw altitude scale
        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'left';
        ctx.strokeStyle = COLORS.CYAN_INFO;
        ctx.fillStyle = COLORS.CYAN_INFO;
        ctx.lineWidth = 1;

        const minAlt = Math.floor((altitudeFeet - 200) / 50) * 50;
        const maxAlt = Math.ceil((altitudeFeet + 200) / 50) * 50;

        for (let alt = minAlt; alt <= maxAlt; alt += 25) {
            const y = centerY - (alt - altitudeFeet) * pixelsPerFoot;

            if (y >= centerY - height/2 && y <= centerY + height/2) {
                const isMajorMark = alt % 100 === 0;

                ctx.beginPath();
                ctx.moveTo(x, y);
                ctx.lineTo(x + (isMajorMark ? 15 : 8), y);
                ctx.stroke();

                if (isMajorMark && alt >= 0) {
                    ctx.fillText(alt.toString(), x + 18, y + 4);
                }
            }
        }

        // Draw current altitude readout (integrated style)
        const readoutY = centerY - 12;
        ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
        ctx.fillRect(x + width - 50, readoutY, 45, 24);

        ctx.strokeStyle = COLORS.CYAN_INFO;
        ctx.lineWidth = 1;
        ctx.strokeRect(x + width - 50, readoutY, 45, 24);

        ctx.fillStyle = COLORS.CYAN_INFO;
        ctx.textAlign = 'center';
        ctx.font = '14px Arial, sans-serif';
        ctx.fillText(Math.round(altitudeFeet).toString(), x + width - 27, centerY + 4);

        // Draw tape border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);
    }

    /**
     * Draw Integrated Digital Readouts
     */
    function drawIntegratedReadouts() {
        // Draw heading indicator at top center
        const heading = telemetryData.hdg || 0;
        const headingX = DISPLAY.ATTITUDE_CENTER_X;
        const headingY = 30;

        ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
        ctx.fillRect(headingX - 20, headingY - 10, 40, 20);

        ctx.strokeStyle = COLORS.MAGENTA_NAV;
        ctx.lineWidth = 1;
        ctx.strokeRect(headingX - 20, headingY - 10, 40, 20);

        ctx.fillStyle = COLORS.MAGENTA_NAV;
        ctx.textAlign = 'center';
        ctx.font = '12px Arial, sans-serif';
        ctx.fillText(Math.round(heading).toString().padStart(3, '0') + '°', headingX, headingY + 3);

        // Draw vertical speed indicator
        const verticalSpeed = (telemetryData.vz || 0) * 196.85; // m/s to ft/min
        if (Math.abs(verticalSpeed) > 50) {
            const vsX = DISPLAY.WIDTH - 30;
            const vsY = DISPLAY.ATTITUDE_CENTER_Y;

            ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
            ctx.fillRect(vsX - 15, vsY - 10, 30, 20);

            ctx.strokeStyle = COLORS.GREEN_NORMAL;
            ctx.lineWidth = 1;
            ctx.strokeRect(vsX - 15, vsY - 10, 30, 20);

            ctx.fillStyle = COLORS.GREEN_NORMAL;
            ctx.textAlign = 'center';
            ctx.font = '10px Arial, sans-serif';
            ctx.fillText(Math.round(verticalSpeed/100).toString() + '00', vsX, vsY + 3);
        }
    }

    /**
     * Draw Flight Director (Command Bars)
     */
    function drawFlightDirector() {
        // This would integrate flight director command bars
        // For now, we'll draw a simple cross-hair reference
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;

        ctx.strokeStyle = COLORS.MAGENTA_NAV;
        ctx.lineWidth = 2;

        // Horizontal command bar placeholder
        ctx.beginPath();
        ctx.moveTo(centerX - 15, centerY);
        ctx.lineTo(centerX + 15, centerY);
        ctx.stroke();

        // Vertical command bar placeholder
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - 15);
        ctx.lineTo(centerX, centerY + 15);
        ctx.stroke();
    }

    /**
     * Update Status Overlays
     */
    function updateStatusOverlays() {
        // Update flight mode display
        const flightModeDisplay = document.getElementById('flight-mode-display');
        if (flightModeDisplay) {
            const mode = telemetryData.mode || 'UNKNOWN';
            const modeAbbreviations = {
                'STABILIZE': 'STAB',
                'ALT_HOLD': 'ALT',
                'POS_HOLD': 'POS',
                'LOITER': 'LOIT',
                'GUIDED': 'GUID',
                'RTL': 'RTL',
                'LAND': 'LAND',
                'AUTO': 'AUTO',
                'BRAKE': 'BRK'
            };
            flightModeDisplay.textContent = modeAbbreviations[mode] || mode;
        }

        // Update armed status
        const armedIndicator = document.getElementById('armed-status-indicator');
        if (armedIndicator) {
            const armed = telemetryData.armed;
            armedIndicator.textContent = armed ? 'ARMED' : 'SAFE';
            armedIndicator.className = armed ? 'armed-indicator armed' : 'armed-indicator';
        }

        // Update battery voltage
        const batteryVoltage = document.getElementById('battery-voltage');
        if (batteryVoltage) {
            const voltage = telemetryData.battery_voltage || 0;
            batteryVoltage.textContent = voltage.toFixed(1) + 'V';

            // Color coding
            if (voltage > 12.6) {
                batteryVoltage.style.color = COLORS.GREEN_NORMAL;
            } else if (voltage > 11.1) {
                batteryVoltage.style.color = COLORS.YELLOW_CAUTION;
            } else {
                batteryVoltage.style.color = COLORS.RED_WARNING;
            }
        }

        // Update current draw
        const currentDraw = document.getElementById('current-draw');
        if (currentDraw) {
            const current = telemetryData.current || 0;
            currentDraw.textContent = current.toFixed(1) + 'A';
            currentDraw.style.color = current > 20 ? COLORS.YELLOW_CAUTION : COLORS.GREEN_NORMAL;
        }

        // Update GPS status
        const gpsStatus = document.getElementById('gps-status');
        if (gpsStatus) {
            const fixType = telemetryData.gps_fix_type || 0;
            const sats = telemetryData.satellites_visible || 0;
            const fixTypes = ['NO GPS', 'NO FIX', '2D', '3D', 'DGPS', 'RTK FL', 'RTK FX'];
            const fixName = fixTypes[fixType] || 'UNK';

            gpsStatus.textContent = `${fixName} ${sats}S`;

            if (fixType >= 3) {
                gpsStatus.style.color = COLORS.GREEN_NORMAL;
            } else if (fixType >= 2) {
                gpsStatus.style.color = COLORS.YELLOW_CAUTION;
            } else {
                gpsStatus.style.color = COLORS.RED_WARNING;
            }
        }

        // Update position display
        const positionDisplay = document.getElementById('position-display');
        if (positionDisplay) {
            const lat = telemetryData.lat || 0;
            const lon = telemetryData.lon || 0;

            if (lat !== 0 && lon !== 0) {
                const latFormatted = Math.abs(lat).toFixed(6) + (lat >= 0 ? 'N' : 'S');
                const lonFormatted = Math.abs(lon).toFixed(6) + (lon >= 0 ? 'E' : 'W');
                positionDisplay.textContent = `${latFormatted} ${lonFormatted}`;
            } else {
                positionDisplay.textContent = 'LAT -- LON --';
            }
        }
    }

    /**
     * Handle Telemetry Update
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    /**
     * Handle Connection Change
     */
    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            telemetryData = {};
        }
    }

    /**
     * Handle Resize
     */
    function handleResize() {
        setTimeout(() => {
            setupHighDPI();
        }, 100);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,
        getTelemetryData: () => ({ ...telemetryData }),
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

